import React, { useState, useEffect } from 'react';
import './App.css';

const ASSETS = [
  {
    symbol: 'BTC',
    name: 'Bitcoin',
    feedId: '0xe62df6c8b4a85fe1a67db44dc12de5db330f7ac66b72dc658afedf0f4a415b43'
  },
  {
    symbol: 'ETH', 
    name: 'Ethereum',
    feedId: '0xff61491a931112ddf1bd8147cd1b641375f79f5825126d665480874634fd0ace'
  },
  {
    symbol: 'SOL',
    name: 'Solana', 
    feedId: '0xef0d8b6fda2ceba41da15d4095d1da392a0d2f8ed0c6c7bc0f4cfac8c280b56d'
  }
];

const FLASH_DURATION = 3000; // 3 seconds

function App() {
  const [gameState, setGameState] = useState('waiting'); // waiting, flashing, answering, gameOver
  const [currentAsset, setCurrentAsset] = useState(null);
  const [currentPrice, setCurrentPrice] = useState(null);
  const [choices, setChoices] = useState([]);
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [loading, setLoading] = useState(false);

  const formatPrice = (price) => {
    const num = parseFloat(price);
    if (num >= 1000) {
      return `$${num.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
    }
    return `$${num.toFixed(2)}`;
  };

  const fetchPrice = async (feedId) => {
    try {
      const response = await fetch(`https://hermes.pyth.network/v2/updates/price/latest?ids[]=${feedId}`);
      const data = await response.json();
      const priceData = data.parsed[0].price;
      const price = parseInt(priceData.price) * Math.pow(10, priceData.expo);
      return price;
    } catch (error) {
      console.error('Failed to fetch price:', error);
      throw error;
    }
  };

  const generateWrongAnswers = (correctPrice) => {
    const wrongAnswers = [];
    const basePrice = correctPrice;

    // Generate 3 wrong answers within reasonable range
    for (let i = 0; i < 3; i++) {
      let wrongPrice;
      do {
        const variation = (Math.random() - 0.5) * 0.2; // ±10% variation
        wrongPrice = basePrice * (1 + variation);
        wrongPrice = Math.max(wrongPrice, 0.01); // Ensure positive
      } while (wrongAnswers.some(p => Math.abs(p - wrongPrice) < basePrice * 0.01)); // Avoid duplicates

      wrongAnswers.push(wrongPrice);
    }

    return wrongAnswers;
  };

  const startNewRound = async () => {
    setLoading(true);
    setGameState('flashing');

    try {
      // Pick random asset
      const asset = ASSETS[Math.floor(Math.random() * ASSETS.length)];
      setCurrentAsset(asset);

      // Fetch current price
      const price = await fetchPrice(asset.feedId);
      setCurrentPrice(price);

      // Generate choices
      const wrongAnswers = generateWrongAnswers(price);
      const allChoices = [price, ...wrongAnswers].sort(() => Math.random() - 0.5);
      setChoices(allChoices);

      setLoading(false);

      // Flash for 3 seconds then show choices
      setTimeout(() => {
        setGameState('answering');
      }, FLASH_DURATION);

    } catch (error) {
      console.error('Error starting round:', error);
      setLoading(false);
      setGameState('waiting');
    }
  };

  const handleAnswer = (selectedPrice) => {
    if (selectedPrice === currentPrice) {
      // Correct!
      const newStreak = streak + 1;
      setStreak(newStreak);
      if (newStreak > bestStreak) {
        setBestStreak(newStreak);
      }
      setGameState('waiting');
    } else {
      // Wrong - game over
      setGameState('gameOver');
    }
  };

  const resetGame = () => {
    setStreak(0);
    setGameState('waiting');
    setCurrentAsset(null);
    setCurrentPrice(null);
    setChoices([]);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>DADAD</h1>
        <p>Crypto Price Memory Challenge</p>
        <div className="stats">
          <div>Current Streak: <strong>{streak}</strong></div>
          <div>Best Streak: <strong>{bestStreak}</strong></div>
        </div>
      </header>

      <main className="game-area">
        {gameState === 'waiting' && (
          <div className="waiting-state">
            <h2>Ready for the next card?</h2>
            <p>You'll see a crypto price for 3 seconds, then pick the correct price from 4 options.</p>
            <button 
              className="start-btn" 
              onClick={startNewRound}
              disabled={loading}
            >
              {loading ? 'Loading...' : streak === 0 ? 'Start Game' : 'Next Card'}
            </button>
          </div>
        )}

        {gameState === 'flashing' && currentAsset && currentPrice && (
          <div className="flash-card">
            <h2>{currentAsset.name} ({currentAsset.symbol})</h2>
            <div className="price-display">
              {formatPrice(currentPrice)}
            </div>
            <div className="timer-bar">
              <div className="timer-fill"></div>
            </div>
          </div>
        )}

        {gameState === 'answering' && currentAsset && choices.length > 0 && (
          <div className="answer-state">
            <h2>What was the price of {currentAsset.name}?</h2>
            <div className="choices">
              {choices.map((price, index) => (
                <button
                  key={index}
                  className="choice-btn"
                  onClick={() => handleAnswer(price)}
                >
                  {formatPrice(price)}
                </button>
              ))}
            </div>
          </div>
        )}

        {gameState === 'gameOver' && (
          <div className="game-over">
            <h2>Game Over!</h2>
            <p>You got {streak} cards correct in a row.</p>
            {streak === bestStreak && streak > 0 && (
              <p className="new-record">🎉 New personal best!</p>
            )}
            <div className="correct-answer">
              The correct price was: <strong>{formatPrice(currentPrice)}</strong>
            </div>
            <button className="restart-btn" onClick={resetGame}>
              Play Again
            </button>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 40px;
}

.header h1 {
  font-size: 3rem;
  font-weight: bold;
  margin-bottom: 10px;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.header p {
  font-size: 1.2rem;
  opacity: 0.9;
  margin-bottom: 20px;
}

.stats {
  display: flex;
  gap: 30px;
  justify-content: center;
  font-size: 1.1rem;
}

.game-area {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 40px;
  text-align: center;
  min-width: 400px;
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.2);
}

.waiting-state h2 {
  margin-bottom: 20px;
  font-size: 1.8rem;
}

.waiting-state p {
  margin-bottom: 30px;
  opacity: 0.9;
  line-height: 1.5;
}

.start-btn {
  background: linear-gradient(45deg, #4CAF50, #45a049);
  color: white;
  border: none;
  padding: 15px 30px;
  font-size: 1.2rem;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-weight: bold;
}

.start-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(76, 175, 80, 0.4);
}

.start-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.flash-card {
  position: relative;
}

.flash-card h2 {
  font-size: 2rem;
  margin-bottom: 30px;
}

.price-display {
  font-size: 4rem;
  font-weight: bold;
  margin-bottom: 30px;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  color: #FFD700;
}

.timer-bar {
  width: 100%;
  height: 6px;
  background: rgba(255,255,255,0.2);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 20px;
}

.timer-fill {
  height: 100%;
  background: linear-gradient(90deg, #4CAF50, #FFC107, #F44336);
  animation: countdown 3s linear forwards;
}

@keyframes countdown {
  from { width: 100%; }
  to { width: 0%; }
}

.answer-state h2 {
  font-size: 1.8rem;
  margin-bottom: 30px;
}

.choices {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
  margin-top: 20px;
}

.choice-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.3);
  padding: 20px;
  font-size: 1.3rem;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-weight: bold;
}

.choice-btn:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255,255,255,0.2);
}

.game-over {
  text-align: center;
}

.game-over h2 {
  font-size: 2.5rem;
  margin-bottom: 20px;
  color: #FF6B6B;
}

.game-over p {
  font-size: 1.3rem;
  margin-bottom: 15px;
}

.new-record {
  font-size: 1.5rem !important;
  color: #FFD700;
  margin-bottom: 20px !important;
}

.correct-answer {
  background: rgba(255, 255, 255, 0.1);
  padding: 20px;
  border-radius: 10px;
  margin: 20px 0;
  font-size: 1.2rem;
}

.restart-btn {
  background: linear-gradient(45deg, #FF6B6B, #ee5a5a);
  color: white;
  border: none;
  padding: 15px 30px;
  font-size: 1.2rem;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-weight: bold;
  margin-top: 20px;
}

.restart-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255, 107, 107, 0.4);
}

@media (max-width: 600px) {
  .app {
    padding: 10px;
  }

  .header h1 {
    font-size: 2rem;
  }

  .game-area {
    min-width: auto;
    width: 100%;
    max-width: 400px;
    padding: 20px;
  }

  .price-display {
    font-size: 2.5rem;
  }

  .choices {
    grid-template-columns: 1fr;
  }

  .stats {
    gap: 15px;
    font-size: 1rem;
  }
}
